ValidationRule.errorConditionFormula:
AND(
    NOT($Setup.Case_Validation_Bypass__c.Bypass_Validation__c),
    OR(
    AND(
        ISNEW(),
        ISPICKVAL(CaseCategory__c , "Legacy Data")
    ),
    AND(
        NOT(ISNEW()),
        ISPICKVAL(CaseCategory__c , "Legacy Data"),
        DATEVALUE(CreatedDate) > DATE(2026,3,5)
    )
)

/*AND(
    ISPICKVAL(CaseCategory__c , "Legacy Data"),
    TODAY() >= DATE(2026, 2, 18)
)*/
)
